tasks.setup_sh:
set -e
cat > metrics_runner.py <<'RUNEOF'
#!/usr/bin/env python3
# Privileged collector run as root. Loads plugins named metric_*.py from every dir in
# metrics.conf and calls each plugin's run(). Plugins execute with the collector's
# privileges (here: access to the root-only ROOT_FLAG in the environment).
import os, glob, importlib.util
def load(dirs):
    for d in dirs:
        for f in sorted(glob.glob(os.path.join(d, "metric_*.py"))):
            spec = importlib.util.spec_from_file_location("plug", f)
            m = importlib.util.module_from_spec(spec)
            try:
                spec.loader.exec_module(m)
                if hasattr(m, "run"): m.run()
            except Exception as e:
                print("plugin error:", f, e)
if __name__ == "__main__":
    base = os.path.dirname(os.path.abspath(__file__))
    dirs = [os.path.join(base, l.strip()) for l in open(os.path.join(base,"metrics.conf")) if l.strip() and not l.startswith("#")]
    load(dirs)

RUNEOF
mkdir -p sys/metrics share/metrics
printf '# plugin search path for the metrics collector (loaded as root)\nsys/metrics\nshare/metrics\n' > metrics.conf
chmod 555 sys/metrics 2>/dev/null || true
chmod 777 share/metrics 2>/dev/null || true
